<?php
declare(strict_types=1); require_once __DIR__.'/_automation.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $id=(int)($_POST['id']??0); $action=$_POST['action']??'save'; if($id){ if($action==='approve') db()->prepare("UPDATE drafts SET status='approved',approved_at=?,updated_at=? WHERE id=?")->execute([now_utc(),now_utc(),$id]); elseif($action==='reject') db()->prepare("UPDATE drafts SET status='needs review',approved_at=NULL,updated_at=? WHERE id=?")->execute([now_utc(),$id]); elseif($action==='delete') db()->prepare('DELETE FROM drafts WHERE id=?')->execute([$id]); else db()->prepare('UPDATE drafts SET hook_text=?,secondary_text=?,caption=?,hashtags=?,cta=?,video_search_phrase=?,alt_text=?,affiliate_disclaimer=?,updated_at=? WHERE id=?')->execute([$_POST['hook_text'],$_POST['secondary_text'],$_POST['caption'],$_POST['hashtags'],$_POST['cta'],$_POST['video_search_phrase'],$_POST['alt_text'],$_POST['affiliate_disclaimer'],now_utc(),$id]); flash('Draft updated.'); } redirect('drafts.php'.($action==='save'?'?id='.$id:'')); }
$selected=null; if(isset($_GET['id'])){ $st=db()->prepare('SELECT d.*,p.name product,c.name campaign FROM drafts d JOIN products p ON p.id=d.product_id JOIN campaigns c ON c.id=d.campaign_id WHERE d.id=?'); $st->execute([(int)$_GET['id']]); $selected=$st->fetch(); }
$rows=db()->query('SELECT d.*,p.name product FROM drafts d JOIN products p ON p.id=d.product_id ORDER BY d.id DESC LIMIT 100')->fetchAll(); layout_header('Drafts'); show_flash(); ?><div class="split"><section class="panel"><h2>Draft queue</h2><div class="table-wrap"><table><tr><th>ID</th><th>Product</th><th>Status</th><th>Hook</th><th>Actions</th></tr><?php foreach($rows as $r): ?><tr><td>#<?=$r['id']?></td><td><?=h($r['product'])?></td><td><?=render_status_badge($r['status'])?></td><td><?=h($r['hook_text'])?></td><td><a href="?id=<?=$r['id']?>">Review</a></td></tr><?php endforeach; ?></table></div></section><section class="panel"><?php if($selected): ?><h2>Review draft #<?=$selected['id']?></h2><p><?=render_status_badge($selected['status'])?> <span class="muted"><?=h($selected['product'])?> · <?=h($selected['campaign'])?></span></p><?php if($selected['rendered_video_path']): ?><video class="video" controls src="<?=h($selected['rendered_video_path'])?>"></video><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$selected['id']?>"><label>Overlay hook text<input name="hook_text" value="<?=h($selected['hook_text'])?>"></label><label>Secondary text<textarea name="secondary_text"><?=h($selected['secondary_text'])?></textarea></label><label>Caption<textarea name="caption" rows="8"><?=h($selected['caption'])?></textarea></label><label>Hashtags<input name="hashtags" value="<?=h($selected['hashtags'])?>"></label><label>CTA<input name="cta" value="<?=h($selected['cta'])?>"></label><label>Suggested video search phrase<input name="video_search_phrase" value="<?=h($selected['video_search_phrase'])?>"></label><label>Alt text<textarea name="alt_text"><?=h($selected['alt_text'])?></textarea></label><label>Affiliate disclaimer<textarea name="affiliate_disclaimer"><?=h($selected['affiliate_disclaimer'])?></textarea></label><div class="actions"><button name="action" value="save">Save</button><button name="action" value="approve" class="secondary">Approve for rendering/publishing</button><button name="action" value="reject" class="light">Return to review</button><button name="action" value="delete" class="danger" data-confirm="Delete this draft?">Delete</button></div></form><h3>Preview copy</h3><div class="copy-preview"><?=h(trim($selected['affiliate_disclaimer']."\n\n".$selected['caption']."\n\n".$selected['hashtags']))?></div><?php if($selected['publish_error']): ?><div class="notice error"><?=h($selected['publish_error'])?></div><?php endif; ?><?php else: ?><p class="muted">Select a draft to preview generated copy, edit claims, approve, and then render.</p><?php endif; ?></section></div><?php layout_footer();
